test('dashboard: top customers by due amount', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 50 }],
  });
  assert(inv1.ok);
  const inv1Issue = issueInvoice(inv1.value, []);
  assert(inv1Issue.ok);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 20 }],
  });
  assert(inv2.ok);
  const inv2Issue = issueInvoice(inv2.value, ['INV-2026-0001']);
  assert(inv2Issue.ok);

  const inv3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert(inv3.ok);
  const inv3Issue = issueInvoice(inv3.value, ['INV-2026-0001', 'INV-2026-0002']);
  assert(inv3Issue.ok);

  const result = dashboard([inv1Issue.value, inv2Issue.value, inv3Issue.value], '2026-10-20');

  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C-001');
  assert(result.topCustomers[0].due > result.topCustomers[1].due);
  assert(result.topCustomers[1].due > result.topCustomers[2].due);
});

test('dashboard: top 3 customers only', () => {
  const invoices = [];
  for (let i = 1; i <= 5; i++) {
    const inv = createInvoice({
      customerId: `C-00${i}`,
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: i * 5 }],
    });
    assert(inv.ok);
    const invIssue = issueInvoice(inv.value, []);
    assert(invIssue.ok);
    invoices.push(invIssue.value);
  }

  const result = dashboard(invoices, '2026-10-20');

  assert.equal(result.topCustomers.length, 3);
});

